                                    valueType == "String" ||
                                    valueType == "type" ||
                                    valueType == "null" || valueType == "any" ||
                                    valueType == "list" || valueType == "dict" ||
                                    valueType == "buffer" || valueType == "handle" ||
                                    classes_.find(valueType) != classes_.end();
